patch:
--- a/Source/FPSGAME/WorldGeneration/VillagePlantingDisplay.cpp
+++ b/Source/FPSGAME/WorldGeneration/VillagePlantingDisplay.cpp
@@ -1,4 +1,6 @@
 #include "VillagePlantingDisplay.h"
+#include "TemperateVillagePlanting.h"
+#include "TemperateVillageGround.h"
 #include "VillageCanopyDetail.h"
 #include "ProfilingDebugging/CpuProfilerTrace.h"
 #include "TemperateHillsWorld.h"
@@ -45,13 +47,14 @@
         Cell=Area;Cell.Max.X=FMath::Min(Cell.Min.X+2000.,Area.Max.X);
         Cell.Max.Y=FMath::Min(Cell.Min.Y+2000.,Area.Max.Y);NextY=Cell.Min.Y;
     }
-    if(!Neighborhood)
+    const bool AuthoredForest=Hills->IsForestVillage();
+    if(!AuthoredForest && !Neighborhood)
     {
         // Retain the same finite competition halo and world-space candidate IDs.
         // Preparing the whole village at once was an unbudgeted 55 ms work unit.
         Neighborhood=Hills->BeginVegetationCell(Cell);return;
     }
-    if(!RelationshipsReady)
+    if(!AuthoredForest && !RelationshipsReady)
     {
         RelationshipsReady=Hills->AdvanceVegetationCell(Neighborhood,true);return;
     }
@@ -67,7 +70,25 @@
         {
             Pending.Reset();PendingIndex=0;
             FBox Strip=Cell;Strip.Min.Y=NextY;Strip.Max.Y=FMath::Min(NextY+200.,Cell.Max.Y);
-            Hills->GetVegetationStrip(2,Strip,*Neighborhood,Pending);Hills->GetVegetationStrip(4,Strip,*Neighborhood,Pending);Hills->GetVegetationStrip(3,Strip,*Neighborhood,Pending);
+            if(AuthoredForest)
+            {
+                // Only the village-owned plant beds and gravel belong on the annex.
+                const auto& Site=Hills->GetVillageSite();
+                Strip.Min.Y=FMath::Max(Strip.Min.Y,Site.Ground.Y-Site.PadHalfX-100.);
+                if(Strip.Min.Y<Strip.Max.Y)
+                {
+                    TemperateVillageGround::GatherStrip(*Hills,Strip,Pending);
+                    for(auto& Stone:Pending) Stone.bVillagePlanting=true;
+                    TemperateVillagePlanting::Gather(*Hills,4,Strip,Pending);
+                    TemperateVillagePlanting::Gather(*Hills,3,Strip,Pending);
+                }
+            }
+            else
+            {
+                Hills->GetVegetationStrip(2,Strip,*Neighborhood,Pending);
+                Hills->GetVegetationStrip(4,Strip,*Neighborhood,Pending);
+                Hills->GetVegetationStrip(3,Strip,*Neighborhood,Pending);
+            }
             NextY=Strip.Max.Y;
         }
         constexpr int32 MaxCandidatesPerBatch = 32;
